import React, { useState, useEffect } from 'react';
import { roomAPI, bookingAPI, adminAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const AdminDashboard = () => {
  const { user } = useAuth();
    // Rediriger si ce n'est pas un admin
  if (user && user.role !== 'admin') {
    if (user.role === 'client') {
      return <Navigate to="/client/dashboard" />;
    }
    if (user.role === 'owner') {
      return <Navigate to="/owner/dashboard" />;
    }
    return <Navigate to="/" />;
  }
  const [users, setUsers] = useState([]);
  const [allRooms, setAllRooms] = useState([]);
  const [allBookings, setAllBookings] = useState([]);
  const [loading, setLoading] = useState({
    users: true,
    rooms: true,
    bookings: true
  });
  const [activeTab, setActiveTab] = useState('users');

  useEffect(() => {
    if (user && user.role === 'admin') {
      fetchAdminData();
    }
  }, [user]);

  const fetchAdminData = async () => {
    await Promise.all([
      fetchAllUsers(),
      fetchAllRooms(),
      fetchAllBookings()
    ]);
  };

  const fetchAllUsers = async () => {
    try {
      const response = await adminAPI.getAllUsers();
      setUsers(response.data.users || []);
    } catch (error) {
      console.error('Erreur chargement utilisateurs:', error);
    } finally {
      setLoading(prev => ({ ...prev, users: false }));
    }
  };

  const fetchAllRooms = async () => {
    try {
      const response = await roomAPI.getAll({ limit: 100 });
      setAllRooms(response.data.rooms || []);
    } catch (error) {
      console.error('Erreur chargement salles:', error);
    } finally {
      setLoading(prev => ({ ...prev, rooms: false }));
    }
  };

   const fetchAllBookings = async () => {
    try {
      // Pour l'instant, on utilise une route temporaire
      const response = await adminAPI.getAllBookings();
      setAllBookings(response.data.bookings || []);
    } catch (error) {
      console.error('Erreur chargement réservations:', error);
      // Si la route n'existe pas, on laisse un tableau vide
      setAllBookings([]);
    } finally {
      setLoading(prev => ({ ...prev, bookings: false }));
    }
  };
  const handleUpdateUserRole = async (userId, newRole) => {
    if (!window.confirm(`Changer le rôle de cet utilisateur en "${newRole}" ?`)) return;
    
    try {
      const response = await adminAPI.updateUserRole(userId, { role: newRole });
      if (response.success) {
        // Mettre à jour localement
        setUsers(users.map(user => 
          user.id === userId ? { ...user, role: newRole } : user
        ));
      }
    } catch (error) {
      console.error('Erreur mise à jour rôle:', error);
    }
  };

  const handleDeleteRoom = async (roomId) => {
    if (!window.confirm('Supprimer cette salle ?')) return;
    
    try {
      const response = await roomAPI.delete(roomId);
      if (response.success) {
        setAllRooms(allRooms.filter(r => r.id !== roomId));
      }
    } catch (error) {
      console.error('Erreur suppression salle:', error);
    }
  };

  const handleDeleteBooking = async (bookingId) => {
    if (!window.confirm('Supprimer cette réservation ?')) return;
    
    try {
      const response = await bookingAPI.delete(bookingId);
      if (response.success) {
        setAllBookings(allBookings.filter(b => b.id !== bookingId));
      }
    } catch (error) {
      console.error('Erreur suppression réservation:', error);
    }
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>🛡️ Administration</h1>
        <p>Gestion complète de la plateforme</p>
        <p>Connecté en tant que: <strong>{user?.email}</strong></p>
      </div>

      {/* Navigation des onglets */}
      <div className="card">
        <div className="tabs">
          <button 
            className={`tab-btn ${activeTab === 'users' ? 'active' : ''}`}
            onClick={() => setActiveTab('users')}
          >
            👥 Utilisateurs ({users.length})
          </button>
          <button 
            className={`tab-btn ${activeTab === 'rooms' ? 'active' : ''}`}
            onClick={() => setActiveTab('rooms')}
          >
            🏢 Salles ({allRooms.length})
          </button>
          <button 
            className={`tab-btn ${activeTab === 'bookings' ? 'active' : ''}`}
            onClick={() => setActiveTab('bookings')}
          >
            📅 Réservations ({allBookings.length})
          </button>
        </div>
      </div>

      {/* Contenu des onglets */}
      <div className="card">
        {activeTab === 'users' && (
          <>
            <h2>Gestion des utilisateurs</h2>
            {loading.users ? (
              <p>Chargement des utilisateurs...</p>
            ) : (
              <div className="table-container">
                <table className="admin-table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Nom</th>
                      <th>Email</th>
                      <th>Rôle</th>
                      <th>Inscrit le</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.map(userItem => (
                      <tr key={userItem.id}>
                        <td>{userItem.id}</td>
                        <td>{userItem.first_name} {userItem.last_name}</td>
                        <td>{userItem.email}</td>
                        <td>
                          <span className={`role-badge ${userItem.role}`}>
                            {userItem.role}
                          </span>
                        </td>
                        <td>{new Date(userItem.created_at).toLocaleDateString('fr-FR')}</td>
                        <td>
                          <select 
                            value={userItem.role}
                            onChange={(e) => handleUpdateUserRole(userItem.id, e.target.value)}
                            className="role-select"
                          >
                            <option value="client">Client</option>
                            <option value="owner">Propriétaire</option>
                            <option value="admin">Administrateur</option>
                          </select>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </>
        )}

        {activeTab === 'rooms' && (
          <>
            <h2>Gestion des salles</h2>
            {loading.rooms ? (
              <p>Chargement des salles...</p>
            ) : (
              <div className="table-container">
                <table className="admin-table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Titre</th>
                      <th>Propriétaire</th>
                      <th>Ville</th>
                      <th>Capacité</th>
                      <th>Prix</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allRooms.map(room => (
                      <tr key={room.id}>
                        <td>{room.id}</td>
                        <td>{room.title}</td>
                        <td>{room.owner_first_name} {room.owner_last_name}</td>
                        <td>{room.city}</td>
                        <td>{room.capacity}</td>
                        <td>{room.price_per_hour}€</td>
                        <td>
                          <button 
                            onClick={() => handleDeleteRoom(room.id)}
                            className="btn btn-danger btn-sm"
                          >
                            Supprimer
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </>
        )}

        {activeTab === 'bookings' && (
          <>
            <h2>Gestion des réservations</h2>
            {loading.bookings ? (
              <p>Chargement des réservations...</p>
            ) : (
              <div className="table-container">
                <table className="admin-table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Client</th>
                      <th>Salle</th>
                      <th>Dates</th>
                      <th>Prix</th>
                      <th>Statut</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allBookings.map(booking => (
                      <tr key={booking.id}>
                        <td>{booking.id}</td>
                        <td>{booking.client_first_name} {booking.client_last_name}</td>
                        <td>{booking.room_title}</td>
                        <td>
                          {new Date(booking.start_datetime).toLocaleDateString('fr-FR')}
                          <br />
                          au {new Date(booking.end_datetime).toLocaleDateString('fr-FR')}
                        </td>
                        <td>{booking.total_price}€</td>
                        <td>
                          <span className={`status-badge ${booking.status}`}>
                            {booking.status === 'confirmed' ? 'Confirmée' :
                             booking.status === 'pending' ? 'En attente' :
                             booking.status === 'cancelled' ? 'Annulée' : booking.status}
                          </span>
                        </td>
                        <td>
                          <button 
                            onClick={() => handleDeleteBooking(booking.id)}
                            className="btn btn-danger btn-sm"
                          >
                            Supprimer
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </>
        )}
      </div>

      {/* Statistiques */}
      <div className="card">
        <h3>📊 Statistiques globales</h3>
        <div className="stats-grid">
          <div className="stat-card">
            <h3>{users.length}</h3>
            <p>Utilisateurs</p>
          </div>
          <div className="stat-card">
            <h3>{allRooms.length}</h3>
            <p>Salles</p>
          </div>
          <div className="stat-card">
            <h3>{allBookings.length}</h3>
            <p>Réservations</p>
          </div>
          <div className="stat-card">
            <h3>
              {allBookings.reduce((sum, b) => sum + parseFloat(b.total_price || 0), 0).toFixed(2)}€
            </h3>
            <p>Chiffre d'affaires</p>
          </div>
        </div>
      </div>
    </div>
  );
};

// Ajouter ces styles dans App.css
const styles = `
.admin-table {
  width: 100%;
  border-collapse: collapse;
}

.admin-table th,
.admin-table td {
  padding: 12px;
  text-align: left;
  border-bottom: 1px solid #ddd;
}

.admin-table th {
  background-color: #f8f9fa;
  font-weight: bold;
}

.role-badge {
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: bold;
}

.role-badge.admin {
  background-color: #6f42c1;
  color: white;
}

.role-badge.owner {
  background-color: #007bff;
  color: white;
}

.role-badge.client {
  background-color: #28a745;
  color: white;
}

.status-badge {
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: bold;
}

.status-badge.confirmed {
  background-color: #28a745;
  color: white;
}

.status-badge.pending {
  background-color: #ffc107;
  color: #212529;
}

.status-badge.cancelled {
  background-color: #dc3545;
  color: white;
}

.tabs {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.tab-btn {
  padding: 10px 20px;
  border: none;
  background-color: #f8f9fa;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.3s;
}

.tab-btn.active {
  background-color: #007bff;
  color: white;
}

.table-container {
  overflow-x: auto;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px;
  margin-top: 20px;
}

.stat-card {
  background: #f8f9fa;
  padding: 20px;
  border-radius: 8px;
  text-align: center;
}

.stat-card h3 {
  margin: 0;
  font-size: 2rem;
  color: #007bff;
}

.role-select {
  padding: 5px;
  border-radius: 4px;
  border: 1px solid #ddd;
}

.btn-danger {
  background-color: #dc3545;
  color: white;
}

.btn-danger:hover {
  background-color: #c82333;
}

.btn-sm {
  padding: 5px 10px;
  font-size: 14px;
}
`;

// Ajouter les styles au document
const styleSheet = document.createElement("style");
styleSheet.textContent = styles;
document.head.appendChild(styleSheet);

export default AdminDashboard;
